import mq3.client.ui_rankstatus as s
import mq3.client.ui_rankings as r
import mq3.client.ui_qmenu as q
function req(ok,label) if not ok then return error(7995,"rankstatus: "+label) end if;return 1 end function
function main(args) count=0;v=s.create(false);count=count+req(not s.UI_RankStatusMenu(v,r.QGR_STATUS_NEW) and not v.pushed,"new ignored");v=s.create(false);count=count+req(not s.UI_RankStatusMenu(v,r.QGR_STATUS_PENDING),"pending poll");v=s.create(false);count=count+req(not s.UI_RankStatusMenu(v,r.QGR_STATUS_ACTIVE) and v.forcedOff,"active closes menu");v=s.create(false);count=count+req(s.UI_RankStatusMenu(v,r.QGR_STATUS_BAD_PASSWORD) and v.messageText=="Invalid password" and v.pushed,"bad password dialog");count=count+req(len(v.menu.items)==3 and v.message.string=="Invalid password" and v.ok.string=="OK","layout");count=count+req(v.actions[len(v.actions)-2].kind=="reset-user","reset after terminal status");count=count+req(s.RankStatus_MenuEvent(v,s.ID_OK,q.QM_ACTIVATED) and v.popped,"ok pops");count=count+req(v.actions[len(v.actions)-2].name=="rankings" and v.actions[len(v.actions)-1].name=="login","bad password route");v=s.create(false);s.UI_RankStatusMenu(v,r.QGR_STATUS_USER_EXISTS);s.RankStatus_MenuEvent(v,s.ID_OK,q.QM_ACTIVATED);count=count+req(v.actions[len(v.actions)-1].name=="signup","existing user route");v=s.create(true);s.UI_RankStatusMenu(v,r.QGR_STATUS_ERROR);ok=true;for each a in v.actions if a.dispatched then ok=false end if end for;count=count+req(ok,"suppression");print("PASS: "+str(count)+" UI rankstatus contracts");return 0 end function
